// Design-sheet route regeneration against static Editor geometry. No runtime pathfinding.
using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;using System.Security.Cryptography;
public static class ReplanRoutes {
 static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));const float Cell=.25f;const int W=208,H=140;
 static Vector3 Point(int i)=>new Vector3((i%W+.5f)*Cell-24,0,(i/W+.5f)*Cell-16);
 static int Nearest(JToken node,bool[] free){var target=new Vector3((float)node["x"]-24,0,(float)node["y"]-16);int best=-1;float dist=100;for(int i=0;i<free.Length;i++)if(free[i]){float d=(Point(i)-target).sqrMagnitude;if(d<dist){dist=d;best=i;}}if(best<0||dist>1)throw new Exception("Route node unavailable "+node);return best;}
 static List<int> Search(int a,int b,bool[] free){var prev=Enumerable.Repeat(-1,free.Length).ToArray();var q=new Queue<int>();q.Enqueue(a);prev[a]=a;while(q.Count>0){int p=q.Dequeue();if(p==b)break;int x=p%W,y=p/W;foreach(int d in new[]{-1,1,-W,W}){int n=p+d;if(n<0||n>=free.Length||Math.Abs(n%W-x)+Math.Abs(n/W-y)!=1||!free[n]||prev[n]>=0)continue;prev[n]=p;q.Enqueue(n);}}if(prev[b]<0)throw new Exception("Disconnected route "+Point(a)+" "+Point(b));var result=new List<int>();for(int p=b;;p=prev[p]){result.Add(p);if(p==a)break;}result.Reverse();return result;}
 public static object Run(){if(EditorApplication.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit scene required");string original=SceneManager.GetActiveScene().path;string dir=Repo+"/Docs/도면/잠입_탐색/",file=dir+"플레이어_예상이동/player_routes.json";var doc=JObject.Parse(File.ReadAllText(file));var layout=JObject.Parse(File.ReadAllText(dir+"layout.json"));var reports=new List<object>();
  try{foreach(string floor in new[]{"B5","B4","B3"}){EditorSceneManager.OpenScene("Assets/Afrer_Seconds/01.Scenes/Stage/Level_"+floor+"_Stealth.unity");Physics.SyncTransforms();var free=new bool[W*H];int count=0;
   for(int i=0;i<free.Length;i++){var p=Point(i);if(Physics.OverlapCapsule(p+Vector3.up*.36f,p+Vector3.up*1.52f,.32f,~0,QueryTriggerInteraction.Ignore).Any(c=>!c.transform.root.name.StartsWith("Player")))continue;bool ground=Physics.RaycastAll(p+Vector3.up*.25f,Vector3.down,.5f,~0,QueryTriggerInteraction.Ignore).Any(h=>!h.transform.root.name.StartsWith("Player")&&h.normal.y>.75f);if(ground){free[i]=true;count++;}}
   var plan=layout["floors"].Single(f=>(string)f["floor"]==floor);var details=new List<object>();foreach(var route in doc["routes"].Where(r=>(string)r["floor"]==floor)){var nodes=route["nodes"].ToArray();var legs=new JArray();var cells=new List<int>();float length=0;
    for(int leg=0;leg<nodes.Length-1;leg++){var path=Search(Nearest(nodes[leg],free),Nearest(nodes[leg+1],free),free);cells.AddRange(path);var points=new JArray();for(int i=0;i<path.Count;i++){if(i>0&&i<path.Count-1&&path[i]-path[i-1]==path[i+1]-path[i])continue;var p=Point(path[i]);points.Add(new JArray(Math.Round(p.x+24,3),Math.Round(p.z+16,3)));}float metres=(path.Count-1)*Cell;length+=metres;legs.Add(new JObject{{"from",leg},{"to",leg+1},{"length",metres},{"points",points}});}
    route["legs"]=legs;route["walkingMetres"]=Math.Round(length,1);route["staticGeometryChecked"]=true;route["geometryDate"]="2026-11-06";
    var risks=new JArray();foreach(var cam in plan["cameras"]){float u=(float)cam["x"],v=(float)cam["y"],range=(float)cam["range"],angle=(float)cam["angle"],fov=(float)cam["fov"];var room=plan["rooms"].Single(r=>(string)r["id"]==(string)cam["room"]);foreach(int i in cells){var p=Point(i);float x=p.x+24,y=p.z+16;if(x<(float)room["x"]||x>(float)room["x"]+(float)room["w"]||y<(float)room["y"]||y>(float)room["y"]+(float)room["h"])continue;float dx=x-u,dy=y-v;if(dx*dx+dy*dy>range*range||Mathf.Abs(Mathf.DeltaAngle(angle,Mathf.Atan2(dy,dx)*Mathf.Rad2Deg))>fov/2)continue;risks.Add(new JObject{{"camera",(string)cam["id"]},{"x",x},{"y",y},{"leg",0}});break;}}route["cameraOverlaps"]=risks;
    if((string)route["variant"]=="A")plan["walkingExample"]=new JArray(legs.SelectMany(l=>l["points"]).Select(p=>p.DeepClone()));details.Add(new{variant=(string)route["variant"],metres=length,legs=legs.Count,risks=risks.Count});
   }reports.Add(new{floor,freeCells=count,bodyDiameter=.64,details});
  }}finally{EditorSceneManager.OpenScene(original);}File.WriteAllText(dir+"layout.json",layout.ToString(Formatting.Indented),new System.Text.UTF8Encoding(false));using(var sha=SHA256.Create())doc["sourceSHA256"]=BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(dir+"layout.json"))).Replace("-","");doc["scope"]="설계도 복사본. B5/B4/B3 예상 이동은 현재 Unity 정적 충돌·바닥으로 재계산. 게임 코드·미니맵 UI 미구현.";File.WriteAllText(file,doc.ToString(Formatting.Indented),new System.Text.UTF8Encoding(false));File.WriteAllText(Repo+"/Docs/검수/2026-11-06_B345_WideInterior/replanned_routes.json",JsonConvert.SerializeObject(reports,Formatting.Indented));return reports;
 }
}
